module rutra_top (
    input  wire clk,          // 27MHz onboard clock (pin 52)
    input  wire rst_n_btn,    // onboard button S1, active-low (pin 4)
    output wire uart_tx,      // UART to PC via onboard USB bridge (pin 17)
    input  wire uart_rx,      // UART from PC via onboard USB bridge (pin 18)
    output wire tmds_clk_p, tmds_clk_n,
    output wire [2:0] tmds_d_p, tmds_d_n
);


    // ---------------------------------------------------------
    // Clocks
    // serial_clk = 5 x pixel_clk  (generated by the rPLL from 27MHz)
    // pixel_clk  = serial_clk / 5 (generated by CLKDIV)
    // ---------------------------------------------------------
    wire serial_clk;   // target ~126MHz
    wire pixel_clk;    // target ~25.2MHz
    wire pll_lock;

    Gowin_rPLL rpll_inst (
        .clkout (serial_clk),
        .lock   (pll_lock),
        .clkin  (clk)
    );

    wire clk_rst_n = rst_n_btn & pll_lock;

    CLKDIV #(
        .DIV_MODE("5"),
        .GSREN("false")
    ) u_clkdiv (
        .CLKOUT (pixel_clk),
        .HCLKIN (serial_clk),
        .RESETN (clk_rst_n),
        .CALIB  (1'b0)
    );

    // ---------------------------------------------------------
    // Video timing
    // ---------------------------------------------------------
    wire hsync, vsync, active;
    wire [9:0] x, y;

    video_timing u_timing (
        .pixel_clk (pixel_clk),
        .rst_n     (clk_rst_n),
        .hsync     (hsync),
        .vsync     (vsync),
        .active    (active),
        .x         (x),
        .y         (y)
    );

    // ---------------------------------------------------------
    // rutraCPU + rutraGPU
    // ---------------------------------------------------------
    // Bootloader holds the CPU/GPU in reset while a program is being loaded
    wire        boot_hold;
    wire        cpu_reset = ~clk_rst_n | boot_hold;   // active-high reset for CPU/GPU

    localparam MEMORY_ADDRESS_BITS = 10;                // 1024 words of unified 16-bit memory

    wire [15:0] cpu_pc;
    wire [15:0] cpu_r1, cpu_r2;
    wire [MEMORY_ADDRESS_BITS-1:0] cpu_memory_address;
    wire        cpu_memory_write_enable;
    wire [15:0] cpu_memory_write_data;
    wire [15:0] cpu_memory_read_data;
    wire [7:0]  cpu_out_data;
    wire        cpu_out_valid;
    wire        cpu_out_is_char;
    wire        cpu_halted;
    wire        gpu_present_pulse;
    wire [7:0]  vid_pixel;

    wire        uart_busy;
    wire        cpu_consumed = ~uart_busy;

    uart_tx #(.CLK_HZ(25_200_000), .BAUD(115200)) u_uart (
        .clk   (pixel_clk),
        .rst_n (clk_rst_n),
        .data  (cpu_out_data),
        .start (cpu_out_valid & ~uart_busy),
        .tx    (uart_tx),
        .busy  (uart_busy)
    );

    wire [3:0]  gpu_cmd;
    wire [15:0] gpu_arg;
    wire        gpu_start;
    wire        gpu_done;
    wire        gpu_ready;

    wire [7:0] vid_x = x[9:2];                      // 640 / 4 = 160
    wire [7:0] vid_y = y[9:2];                      // 480 / 4 = 120

    // ---------------------------------------------------------
    // UART bootloader: receives program, writes it into ROM
    // ---------------------------------------------------------
    wire [7:0]  rx_data;
    wire        rx_valid;
    wire        boot_write_enable;
    wire [MEMORY_ADDRESS_BITS-1:0] boot_write_address;
    wire [15:0] boot_write_data;

    uart_rx #(.CLK_HZ(25_200_000), .BAUD(115200)) u_uart_rx (
        .clk   (pixel_clk),
        .rst_n (clk_rst_n),
        .rx    (uart_rx),
        .data  (rx_data),
        .valid (rx_valid)
    );

    rutra_boot #(.ADDRESS_BITS(MEMORY_ADDRESS_BITS)) u_boot (
        .clk       (pixel_clk),
        .rst_n     (clk_rst_n),
        .uart_rx_data  (rx_data),
        .uart_rx_valid (rx_valid),
        .memory_write_enable  (boot_write_enable),
        .memory_write_address (boot_write_address),
        .memory_write_data    (boot_write_data),
        .hold_cpu_in_reset    (boot_hold)
    );

    rutracpu_memory #(.MEMORY_ADDRESS_BITS(MEMORY_ADDRESS_BITS)) u_memory (
        .clk                (pixel_clk),
        .boot_write_enable  (boot_write_enable),
        .boot_write_address (boot_write_address),
        .boot_write_data    (boot_write_data),
        .cpu_write_enable   (cpu_memory_write_enable),
        .cpu_address        (cpu_memory_address),
        .cpu_write_data     (cpu_memory_write_data),
        .cpu_read_data      (cpu_memory_read_data)
    );

    rutracpu #(.MEMORY_ADDRESS_BITS(MEMORY_ADDRESS_BITS)) u_cpu (
        .clk         (pixel_clk),
        .reset       (cpu_reset),
        .cpu_memory_address    (cpu_memory_address),
        .cpu_memory_write_enable      (cpu_memory_write_enable),
        .cpu_memory_write_data   (cpu_memory_write_data),
        .cpu_memory_read_data   (cpu_memory_read_data),
        .consumed    (cpu_consumed),
        .pc          (cpu_pc),
        .r1          (cpu_r1),
        .r2          (cpu_r2),
        .out_data    (cpu_out_data),
        .out_valid   (cpu_out_valid),
        .out_is_char (cpu_out_is_char),
        .halted      (cpu_halted),
        .gpu_cmd     (gpu_cmd),
        .gpu_arg     (gpu_arg),
        .gpu_start   (gpu_start),
        .gpu_ready   (gpu_ready),
        .gpu_done    (gpu_done)
    );

    rutragpu u_gpu (
        .clk           (pixel_clk),
        .reset         (cpu_reset),
        .command       (gpu_cmd),
        .argument      (gpu_arg),
        .command_start (gpu_start),
        .command_ready (gpu_ready),
        .command_done  (gpu_done),
        .present_frame_pulse (gpu_present_pulse),
        .video_x       (vid_x),
        .video_y       (vid_y),
        .video_pixel   (vid_pixel)
    );

    // ---------------------------------------------------------
    // RGB332 pixel -> 24 bit color
    // sync/DE are delayed to line up with the pixel pipeline:
    // x,y reg (1) + BSRAM read, bypass mode (1) + color reg (1)
    // ---------------------------------------------------------
    localparam PIPE = 3;
    reg [PIPE-1:0] de_d, hs_d, vs_d;
    always @(posedge pixel_clk) begin
        de_d <= {de_d[PIPE-2:0], active};
        hs_d <= {hs_d[PIPE-2:0], hsync};
        vs_d <= {vs_d[PIPE-2:0], vsync};
    end 

    reg [7:0] red, green, blue;
    always @(posedge pixel_clk) begin
        red   <= {vid_pixel[7:5], vid_pixel[7:5], vid_pixel[7:6]};
        green <= {vid_pixel[4:2], vid_pixel[4:2], vid_pixel[4:3]};
        blue  <= {4{vid_pixel[1:0]}};
    end

    // ---------------------------------------------------------
    // DVI TX IP core — handles TMDS encoding + serialization +
    // TLVDS output buffering for all four channels internally.
    // ---------------------------------------------------------
    DVI_TX_Top u_dvi_tx (
        .I_rst_n      (clk_rst_n),
        .I_serial_clk (serial_clk),
        .I_rgb_clk    (pixel_clk),
        .I_rgb_vs     (vs_d[PIPE-1]),
        .I_rgb_hs     (hs_d[PIPE-1]),
        .I_rgb_de     (de_d[PIPE-1]),
        .I_rgb_r      (red),
        .I_rgb_g      (green),
        .I_rgb_b      (blue),
        .O_tmds_clk_p (tmds_clk_p),
        .O_tmds_clk_n (tmds_clk_n),
        .O_tmds_data_p(tmds_d_p),
        .O_tmds_data_n(tmds_d_n)
    );

endmodule